import { View, Text, TouchableOpacity } from 'react-native'
import BottomSheet, {
	BottomSheetBackdrop,
	BottomSheetBackdropProps,
	BottomSheetView
} from '@gorhom/bottom-sheet'
import { Ionicons } from '@expo/vector-icons'
import { Button } from '@/components'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { useRef, useImperativeHandle, useState } from 'react'

export interface DeleteSecretBottomSheetRef {
	open: (id: string) => void
	close: () => void
}

interface DeleteSecretBottomSheetProps {
	bottomInset: number
	onDelete: (id: string) => void
	bottomSheetRef: React.RefObject<DeleteSecretBottomSheetRef | null>
}

export const DeleteSecretBottomSheet = ({
	bottomInset,
	onDelete,
	bottomSheetRef
}: DeleteSecretBottomSheetProps) => {
	const { theme } = useTheme()
	const internalBottomSheetRef = useRef<BottomSheet>(null)
	const [secretId, setSecretId] = useState<string>('')

	useImperativeHandle(
		bottomSheetRef,
		() => ({
			open: (id: string) => {
				setSecretId(id)
				internalBottomSheetRef.current?.snapToIndex(0)
			},
			close: () => {
				internalBottomSheetRef.current?.close()
			}
		}),
		[]
	)

	const handleClose = () => {
		internalBottomSheetRef.current?.close()
	}

	const handleDelete = () => {
		onDelete(secretId)
	}

	const renderBackdrop = (props: BottomSheetBackdropProps) => (
		<BottomSheetBackdrop
			{...props}
			opacity={0.8}
			disappearsOnIndex={-1}
			appearsOnIndex={0}
		/>
	)

	return (
		<BottomSheet
			ref={internalBottomSheetRef}
			bottomInset={bottomInset}
			style={styles.bottomSheetContainer}
			detached={true}
			backdropComponent={renderBackdrop}
			index={-1}
			enablePanDownToClose
			handleComponent={null}
		>
			<BottomSheetView style={styles.bottomSheetContent}>
				<View style={styles.bottomSheetHeader}>
					<Text style={styles.bottomSheetTitle(theme)}>Remove secret</Text>
					<TouchableOpacity onPress={handleClose}>
						<Ionicons name="close" size={24} color={colors[theme].gray[400]} />
					</TouchableOpacity>
				</View>

				<View style={styles.bottomSheetBody}>
					<Text style={styles.bottomSheetMessage(theme)}>
						Are you sure you want to delete this secret?
					</Text>
					<Text style={styles.bottomSheetWarning(theme)}>
						This action is permanent and cannot be undone.
					</Text>
				</View>

				<Button text="Delete" variant="destructive" onPress={handleDelete} />
			</BottomSheetView>
		</BottomSheet>
	)
}

const styles = defineStyles({
	bottomSheetContainer: {
		flex: 1,
		marginHorizontal: 24,
		borderRadius: 48,
		borderCurve: 'continuous',
		overflow: 'hidden'
	},
	bottomSheetContent: {
		padding: 28
	},
	bottomSheetHeader: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center',
		marginBottom: 16
	},
	bottomSheetTitle: (theme: Theme) => ({
		fontSize: 20,
		fontWeight: '600',
		color: colors[theme].gray[900]
	}),
	bottomSheetBody: {
		marginBottom: 24
	},
	bottomSheetMessage: (theme: Theme) => ({
		fontSize: 16,
		lineHeight: 24,
		color: colors[theme].gray[700],
		marginBottom: 12
	}),
	bottomSheetWarning: (theme: Theme) => ({
		fontSize: 16,
		lineHeight: 24,
		fontWeight: '600',
		color: colors[theme].gray[900]
	})
})
